// Oeste OptionRow — Mesa theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with dark: variant, JSX transform.
// Requires Mesa tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/mesa/src/index.js
// Docs: https://oeste.hiddeninwest.com/mesa/#/components/option-row

export function OptionRow({ name, value, checked, onChange, children }) {
  return (
    <label className="mb-2.5 flex cursor-pointer items-start gap-3 rounded-md border border-[#ddd6c7] bg-[#faf9f7] p-3.5 dark:border-[#2e2720] dark:bg-[#100e0b]">
      <input
        type="radio"
        name={name}
        value={value}
        checked={checked}
        onChange={(e) => onChange && onChange(e.target.value)}
        className="mt-[3px] h-[18px] w-[18px] flex-none accent-[#6d1620] dark:accent-[#a52336]"
      />
      <span className="text-[15px]">{children}</span>
    </label>
  );
}
